_("./src/components/Dropdown/DropdownItem.vue"),_components_Dropdown_DropdownGroupItem_vue__WEBPACK_IMPORTED_MODULE_1__=__webpack_require__("./src/components/Dropdown/DropdownGroupItem.vue"),vue__WEBPACK_IMPORTED_MODULE_2__=__webpack_require__("./node_modules/.pnpm/vue@3.5.20_typescript@5.9.2/node_modules/vue/dist/vue.esm-bundler.js");const infoIcon=new URL(__webpack_require__("./src/assets/icon/icon-system/icon-info.svg"),__webpack_require__.b).href,checkIcon=new URL(__webpack_require__("./src/assets/icon/icon-system/icon-check.svg"),__webpack_require__.b).href;__webpack_exports__.default={title:"Components/Dropdown/DropdownItem",component:_components_Dropdown_DropdownItem_vue__WEBPACK_IMPORTED_MODULE_0__.A,tags:["autodocs"],parameters:{docs:{description:{component:"\n### 🎯 DropdownItem\n\nKomponen baris pilihan tunggal (*atomic dropdown item*) yang dirancang untuk membungkus opsi aksi di dalam menu dropdown seperti `DropdownGroupItem` atau menu Bootstrap pada aplikasi **PT Pegadaian (Persero)**. Komponen ini menyediakan padding responsif, garis pemisah halus (*subtle border-bottom*), efek hover transparan terstandarisasi, dan flexbox tata letak `space-between` untuk menyisipkan teks beserta lencana atau ikon penjelas.\n\n---\n\n### 🌟 Fitur Utama Komponen\n\n- 🔘 **Atomic Action Row**: Membungkus elemen native `<button class=\"dropdown-item\">` dengan event klik dan akselerasi keyboard.\n- 📐 **Optimal Layout**: Menggunakan tata letak `d-flex justify-content-between align-items-center` untuk memudahkan perataan teks di sisi kiri dan ikon atau badge status di sisi kanan.\n- 🎨 **Design System Baseline**: Padding 10px vertikal dengan garis pembatas `#EEEEEF` yang rapi dan konsisten dengan komponen form Pegadaian lainnya.\n- 🧩 **Slot Flexibility**: Menerima teks sederhana maupun elemen HTML/komponen Vue kaya di dalam slot `#default`.\n\n---\n\n### 📋 Daftar Props yang Didukung\n\n*Komponen ini tidak memerlukan props khusus, melainkan berfungsi sebagai wadah slot aksi.*\n\n---\n\n### 🧩 Daftar Slots yang Tersedia\n\n| Nama Slot | Keterangan |\n| :--- | :--- |\n| `#default` | Slot utama untuk meletakkan teks label menu aksi, ikon tambahan, atau lencana indikator status. |\n\n---\n\n### 💻 Contoh Penggunaan dalam Vue 3 Script Setup\n\n```vue\n<template>\n  <DropdownGroupItem :src=\"moreIcon\">\n    <DropdownItem @click=\"handleAction('detail')\">\n      <span>Lihat Detail Agunan</span>\n      <img src=\"@/assets/icon/icon-system/icon-check.svg\" alt=\"\" />\n    </DropdownItem>\n    <DropdownItem @click=\"handleAction('print')\">\n      <span>Cetak Salinan SBG</span>\n    </DropdownItem>\n  </DropdownGroupItem>\n</template>\n\n<script setup>\nimport DropdownGroupItem from '@/components/Dropdown/DropdownGroupItem.vue';\nimport DropdownItem from '@/components/Dropdown/DropdownItem.vue';\nimport moreIcon from '@/assets/icon/icon-system/icon-info.svg';\n\nconst handleAction = (type) => {\n  console.log('Action selected:', type);\n};\n<\/script>\n```\n        "}}}};const Default={render:()=>({components:{DropdownItem:_components_Dropdown_DropdownItem_vue__WEBPACK_IMPORTED_MODULE_0__.A},template:'\n      <div class="dropdown-menu show position-static p-2 border rounded shadow-sm" style="max-width: 280px;">\n        <DropdownItem>\n          <span>Detail Surat Bukti Gadai</span>\n        </DropdownItem>\n        <DropdownItem>\n          <span>Perpanjang Tenor Pinjaman</span>\n        </DropdownItem>\n        <DropdownItem>\n          <span>Pelunasan Agunan Emas</span>\n        </DropdownItem>\n      </div>\n    '})},DenganBadgeDanIkon={render:()=>({components:{DropdownItem:_components_Dropdown_DropdownItem_vue__WEBPACK_IMPORTED_MODULE_0__.A},setup(){return{checkIcon:checkIcon}},template:'\n      <div class="dropdown-menu show position-static p-2 border rounded shadow-sm" style="max-width: 300px;">\n        <DropdownItem>\n          <span>Cetak Ulang Polis</span>\n          <span class="badge bg-success small">PDF</span>\n        </DropdownItem>\n        <DropdownItem>\n          <span>Verifikasi Fisik Emas</span>\n          <img :src="checkIcon" width="16" height="16" alt="Verified" />\n        </DropdownItem>\n        <DropdownItem>\n          <span class="text-danger">Batalkan Akad Transaksi</span>\n        </DropdownItem>\n      </div>\n    '}),parameters:{docs:{description:{story:"Menampilkan variasi item menu yang diperkaya dengan lencana status format file atau ikon konfirmasi."}}}},TerintegrasiDropdownGroupItem={render:()=>({components:{DropdownGroupItem:_components_Dropdown_DropdownGroupItem_vue__WEBPACK_IMPORTED_MODULE_1__.A,DropdownItem:_components_Dropdown_DropdownItem_vue__WEBPACK_IMPORTED_MODULE_0__.A},setup(){const selectedAction=(0,vue__WEBPACK_IMPORTED_MODULE_2__.KR)("");return{infoIcon:infoIcon,selectedAction:selectedAction,triggerAction:action=>{selectedAction.value=action}}},template:'\n      <div style="min-height: 200px;">\n        <div class="p-3 bg-light rounded border d-flex align-items-center justify-content-between" style="max-width: 440px;">\n          <div>\n            <div class="fw-bold small text-dark">No. Akad: SBG-2026-JKT-0914</div>\n            <div class="text-muted small">Nasabah: Budi Raharjo (Gadai KCA)</div>\n          </div>\n          <DropdownGroupItem :src="infoIcon">\n            <DropdownItem @click="triggerAction(\'Rincian Taksiran\')">Rincian Taksiran</DropdownItem>\n            <DropdownItem @click="triggerAction(\'Cetak SBG\')">Cetak Surat SBG</DropdownItem>\n            <DropdownItem @click="triggerAction(\'Kirim WhatsApp\')">Kirim Notifikasi WA</DropdownItem>\n          </DropdownGroupItem>\n        </div>\n        <div class="mt-2 small text-muted">\n          Aksi yang dipilih: <strong class="text-success">{{ selectedAction || \'(Klik ikon titik/info di atas)\' }}</strong>\n        </div>\n      </div>\n    '}),parameters:{docs:{description:{story:"Menampilkan integrasi riil `DropdownItem` di dalam komponen kontainer `DropdownGroupItem`."}}}},__named